    88|	if err != nil {
    89|		return nil, errors.Wrap(err, "create tmp dir failed")
    90|	}
    91|	
    92|	// make db set
    93|	server.dbSet = make([]*atomic.Value, config.Properties.Databases)
    94|	for i := range server.dbSet {
    95|		singleDB := makeDBWithSize(dictSize)
    96|		singleDB.index = i
    97|		holder := &atomic.Value{}
    98|		holder.Store(singleDB)
    99|		server.dbSet[i] = holder
   100|	}
   101|	server.hub = pubsub.MakeHub()
   102|	
   103|	// record aof
   104|	validAof := false
   105|	if config.Properties.AppendOnly {
   106|		validAof = fileExists(config.Properties.AppendFilename)
   107|		aofHandler, err := NewPersister(server,
   108|			config.Properties.AppendFilename, true, config.Properties.AppendFsync)
   109|		if err != nil {
   110|			return nil, errors.Wrap(err, "create persister failed")
   111|		}
   112|		server.bindPersister(aofHandler)
   113|	}
   114|	if config.Properties.RDBFilename != "" && !validAof {
   115|		// load rdb
   116|		err := server.loadRdbFile()
   117|		if err != nil {
   118|			logger.Errorf("load rdb file failed: %+v", err)
   119|		}
   120|	}
   121|	server.slaveStatus = initReplSlaveStatus()
   122|	server.initMasterStatus()
   123|	server.startReplCron()
   124|	server.role = masterRole // The initialization process does not require atomicity
   125|
   126|	// record slow log
   127|	server.slogLogger = NewSlowLogger(config.Properties.SlowLogMaxLen, config.Properties.SlowLogSlowerThan)
   128|	
   129|	// initialize lock manager
   130|	server.lockManager = dict.NewLockManager(nil, nil)
   131|	
   132|	// initialize memory limiter
   133|	server.memLimiter = memory.NewLimiter(nil)
   134|	server.memLimiter.Start()
   135|	
   136|	// propagate lock manager to all DBs
   137|	for _, holder := range server.dbSet {
   138|		db := holder.Load().(*DB)
   139|		db.SetLockManager(server.lockManager)
   140|	}
   141|	
   142|	// initialize and propagate eviction manager
   143|	defaultPolicy := memory.ParseEvictionPolicy(config.Properties.MaxmemoryPolicy)
   144|	for _, holder := range server.dbSet {
   145|		db := holder.Load().(*DB)
   146|		em := NewEvictionManager(db, defaultPolicy)
   147|		db.SetEvictionManager(em)
   148|	}
   149|	
   150|	// set up memory limiter eviction callback
   151|	if server.memLimiter.IsEvictionAllowed() {
   152|		server.memLimiter.SetEvictCallback(func(key string) {
   153|			// Try to evict from all DBs
   154|			for _, holder := range server.dbSet {
   155|				db := holder.Load().(*DB)
   156|				db.Remove(key)
   157|			}
   158|		})
   159|	}
   160|
   161|	return server, nil
   162|}
