   173|// Exec executes command
   174|// parameter `cmdLine` contains command and its arguments, for example: "set key value"
   175|func (server *Server) Exec(c redis.Connection, cmdLine [][]byte) (result redis.Reply) {
   176|	defer func() {
   177|		if r := recover(); r != nil {
   178|			logger.Errorf("panic in Exec: %v\n%s", r, string(debug.Stack()))
   179|			result = &protocol.UnknownErrReply{}
   180|		}
   181|	}()
   182|	
   183|	if len(cmdLine) == 0 {
   184|		return protocol.MakeErrReply("ERR unknown command")
   185|	}
   186|	if reply := validateCmdArgCount(cmdLine); reply != nil {
   187|		return reply
   188|	}
   189|
   190|	// Record the start time of command execution
   191|	GodisExecCommandStartUnixTime := time.Now()
   192|
   193|	cmdName := strings.ToLower(string(cmdLine[0]))
   194|	// ping
   195|	if cmdName == "ping" {
   196|		return Ping(c, cmdLine[1:])
   197|	}
   198|	// authenticate
   199|	if cmdName == "auth" {
   200|		return Auth(c, cmdLine[1:])
   201|	}
   202|	if !isAuthenticated(c) {
   203|		return protocol.MakeErrReply("NOAUTH Authentication required")
   204|	}
   205|	// info
   206|	if cmdName == "info" {
   207|		return Info(server, cmdLine[1:])
   208|	}
   209|
   210|	// slowlog
   211|	if cmdName == "slowlog" {
   212|		return server.slogLogger.HandleSlowlogCommand(cmdLine)
   213|	}
   214|
   215|	if cmdName == "dbsize" {
   216|		return DbSize(c, server)
   217|	}
   218|	if cmdName == "slaveof" {
   219|		if c != nil && c.InMultiState() {
   220|			return protocol.MakeErrReply("cannot use slave of database within multi")
   221|		}
   222|		if len(cmdLine) != 3 {
   223|			return protocol.MakeArgNumErrReply("SLAVEOF")
   224|		}
   225|		return server.execSlaveOf(c, cmdLine[1:])
   226|	} else if cmdName == "command" {
   227|		return execCommand(cmdLine[1:])
   228|	} else if cmdName == "config" {
   229|		return execConfig(cmdLine[1:])
   230|	} else if cmdName == "memory" {
   231|		return execMemory(cmdLine[1:])
   232|	} else if cmdName == "latency" {
   233|		return execLatency(cmdLine[1:])
   234|	} else if cmdName == "module" {
   235|		return execModule(cmdLine[1:])
   236|	} else if cmdName == "time" {
   237|		return execTime(cmdLine[1:])
   238|	} else if cmdName == "pubsub" {
   239|		return execPubsub(cmdLine[1:])
   240|	}
   241|
   242|	// read only slave
   243|	role := atomic.LoadInt32(&server.role)
   244|	if role == slaveRole && !c.IsMaster() {
   245|		// only allow read only command, forbid all special commands except `auth` and `slaveof`
   246|		if !isReadOnlyCommand(cmdName) {
   247|			return protocol.MakeErrReply("READONLY You can't write against a read only slave.")
   248|		}
   249|	}
   250|
   251|	// special commands which cannot execute within transaction
   252|	if cmdName == "subscribe" {
   253|		if len(cmdLine) < 2 {
   254|			return protocol.MakeArgNumErrReply("subscribe")
   255|		}
   256|		return pubsub.Subscribe(server.hub, c, cmdLine[1:])
   257|	} else if cmdName == "publish" {
   258|		return pubsub.Publish(server.hub, cmdLine[1:])
   259|	} else if cmdName == "unsubscribe" {
   260|		return pubsub.UnSubscribe(server.hub, c, cmdLine[1:])
   261|	} else if cmdName == "bgrewriteaof" {
   262|		if !config.Properties.AppendOnly {
   263|			return protocol.MakeErrReply("AppendOnly is false, you can't rewrite aof file")
   264|		}
   265|		// aof.go imports router.go, router.go cannot import BGRewriteAOF from aof.go
   266|		return BGRewriteAOF(server, cmdLine[1:])
   267|	} else if cmdName == "rewriteaof" {
   268|		if !config.Properties.AppendOnly {
   269|			return protocol.MakeErrReply("AppendOnly is false, you can't rewrite aof file")
   270|		}
   271|		return RewriteAOF(server, cmdLine[1:])
   272|	} else if cmdName == "flushall" {
   273|		return server.flushAll()
   274|	} else if cmdName == "flushdb" {
   275|		if !validateArity(1, cmdLine) {
   276|			return protocol.MakeArgNumErrReply(cmdName)
   277|		}
   278|		if c.InMultiState() {
   279|			return protocol.MakeErrReply("ERR command 'FlushDB' cannot be used in MULTI")
   280|		}
   281|		return server.execFlushDB(c.GetDBIndex())
   282|	} else if cmdName == "save" {
   283|		return SaveRDB(server, cmdLine[1:])
   284|	} else if cmdName == "bgsave" {
   285|		return BGSaveRDB(server, cmdLine[1:])
   286|	} else if cmdName == "select" {
   287|		if c != nil && c.InMultiState() {
   288|			return protocol.MakeErrReply("cannot select database within multi")
   289|		}
   290|		if len(cmdLine) != 2 {
   291|			return protocol.MakeArgNumErrReply("select")
   292|		}
   293|		dbIndex, err := strconv.Atoi(string(cmdLine[1]))
   294|			if err != nil {
   295|				return protocol.MakeErrReply("ERR invalid DB index")
   296|			}
   297|			if dbIndex >= len(server.dbSet) || dbIndex < 0 {
   298|				return protocol.MakeErrReply("ERR DB index is out of range")
   299|			}
   300|			c.SelectDB(dbIndex)
   301|			return protocol.MakeOkReply()
   302|	} else if cmdName == "swapdb" {
   303|			if len(cmdLine) != 3 {
   304|				return protocol.MakeArgNumErrReply("swapdb")
   305|			}
   306|			index1, err := strconv.Atoi(string(cmdLine[1]))
   307|			if err != nil {
   308|				return protocol.MakeErrReply("ERR value is not an integer or out of range")
   309|			}
   310|			index2, err := strconv.Atoi(string(cmdLine[2]))
   311|			if err != nil {
   312|				return protocol.MakeErrReply("ERR value is not an integer or out of range")
   313|			}
   314|			if index1 < 0 || index1 >= len(server.dbSet) || index2 < 0 || index2 >= len(server.dbSet) {
   315|				return protocol.MakeErrReply("ERR DB index is out of range")
   316|			}
   317|			server.dbSet[index1], server.dbSet[index2] = server.dbSet[index2], server.dbSet[index1]
   318|			currentDB := c.GetDBIndex()
   319|			if currentDB == index1 {
   320|				c.SelectDB(index2)
   321|			} else if currentDB == index2 {
   322|				c.SelectDB(index1)
   323|			}
   324|			server.AddAof(c.GetDBIndex(), utils.ToCmdLine3("swapdb", cmdLine[1:]...))
   325|			return protocol.MakeOkReply()
   326|		} else if cmdName == "copy" {
   327|		if len(cmdLine) < 3 {
   328|			return protocol.MakeArgNumErrReply("copy")
   329|		}
   330|		return execCopy(server, c, cmdLine[1:])
   331|	} else if cmdName == "move" {
   332|		if len(cmdLine) != 3 {
   333|			return protocol.MakeArgNumErrReply("move")
   334|		}
   335|		return server.execMove(c, cmdLine[1:])
   336|	} else if cmdName == "replconf" {
   337|		return server.execReplConf(c, cmdLine[1:])
   338|	} else if cmdName == "psync" {
   339|		return server.execPSync(c, cmdLine[1:])
   340|	}
   341|	// todo: support multi database transaction
   342|
   343|	// normal commands
   344|	dbIndex := c.GetDBIndex()
   345|	selectedDB, errReply := server.selectDB(dbIndex)
   346|	if errReply != nil {
   347|		return errReply
   348|	}
   349|
   350|	exec := selectedDB.Exec(c, cmdLine)
   351|	// Record slow query logs
   352|	server.slogLogger.Record(GodisExecCommandStartUnixTime, cmdLine, c.Name())
   353|	return exec
   354|}
