   614|// GetAvgTTL Calculate the average expiration time of keys
   615|func (server *Server) GetAvgTTL(dbIndex, randomKeyCount int) (int64, error) {
   616|	var ttlCount int64
   617|	db, err := server.selectDBSafe(dbIndex)
   618|	if err != nil {
   619|		return 0, err
   620|	}
   621|	keys := db.data.RandomKeys(randomKeyCount)
   622|	for _, k := range keys {
   623|		t := time.Now()
   624|		rawExpireTime, ok := db.ttlMap.Get(k)
   625|		if !ok {
   626|			continue
   627|		}
   628|		expireTime, _ := rawExpireTime.(time.Time)
   629|		// if the key has already reached its expiration time during calculation, ignore it
   630|		if expireTime.Sub(t).Microseconds() > 0 {
   631|			ttlCount += expireTime.Sub(t).Microseconds()
   632|		}
   633|	}
   634|	if len(keys) == 0 {
   635|		return 0, nil
   636|	}
   637|	return ttlCount / int64(len(keys)), nil
   638|}
